// Public projections are explicit. Never use this transport for authenticated data.
export const componentColumns='id,sku,name,category,manufacturer,description,specs,product_content,individually,in_kits,sale_price,kit_price,image,kit_price_quantity,stock';
export const kitColumns='id,sku,name,category,slug,base_price,show_on_wiring_kits,builder_enabled,default_wiring_style,defaults,builder_options,component_resolvers';
export const optionColumns='option_set,option_key,label,aliases,active,sort_order';
export const productColumns=componentColumns.split(',').filter(key=>!['in_kits','kit_price','kit_price_quantity'].includes(key)).join(',');
export const technicalColumns=componentColumns.split(',').filter(key=>key!=='image').join(',');
const pending=new WeakMap();
// Public rows only. Private transports never enter this cache. Expiry is strict:
// an expired response cannot authorise availability or become an offline fallback.
export const publicCachePolicy=Object.freeze({maxAgeMs:30000,maxEntries:32,maxBytes:20*1024*1024,sessionBytes:256*1024,sessionEntryBytes:64*1024});
const settled=new WeakMap(),generations=new WeakMap();
const sessionKey='apparition.public-catalogue.v1',invalidationKey=sessionKey+'.generation';
function browserStorage(request){try{return request===globalThis.fetch&&globalThis.window?globalThis.sessionStorage:null;}catch{return null;}}
function generation(request){try{return request===globalThis.fetch&&globalThis.window?(globalThis.localStorage?.getItem(invalidationKey)||'')+':'+(generations.get(request)||0):generations.get(request)||0;}catch{return generations.get(request)||0;}}
export function invalidatePublicReads(request=globalThis.fetch){settled.delete(request);pending.delete(request);generations.set(request,(generations.get(request)||0)+1);try{browserStorage(request)?.removeItem(sessionKey);if(request===globalThis.fetch&&globalThis.window)globalThis.localStorage?.setItem(invalidationKey,String(Date.now())+':'+Math.random());}catch{}}
function cache(request){let c=settled.get(request);const g=generation(request);if(!c||c.generation!==g){c={generation:g,entries:new Map()};settled.set(request,c);try{const saved=JSON.parse(browserStorage(request)?.getItem(sessionKey)||'null');if(saved?.generation===g&&Array.isArray(saved.entries))for(const [key,value] of saved.entries.slice(-publicCachePolicy.maxEntries))if(value?.expires>Date.now()&&value.expires<=Date.now()+publicCachePolicy.maxAgeMs&&Array.isArray(value.rows)&&Number.isFinite(value.bytes)&&value.bytes>=0&&value.bytes<=publicCachePolicy.sessionEntryBytes)c.entries.set(key,value);}catch{}}return c;}
function store(request,c,key,rows,expires){const bytes=new TextEncoder().encode(JSON.stringify(rows)).length;if(bytes>publicCachePolicy.maxBytes)return;c.entries.delete(key);c.entries.set(key,{rows:structuredClone(rows),expires,bytes});let total=[...c.entries.values()].reduce((n,e)=>n+e.bytes,0);while(c.entries.size>publicCachePolicy.maxEntries||total>publicCachePolicy.maxBytes){const first=c.entries.keys().next().value;total-=c.entries.get(first).bytes;c.entries.delete(first);}try{const entries=[];let size=0;for(const entry of [...c.entries].reverse()){const value=entry[1];if(value.expires<=Date.now()||value.bytes>publicCachePolicy.sessionEntryBytes)continue;if(size+value.bytes>publicCachePolicy.sessionBytes)continue;size+=value.bytes;entries.unshift(entry);}browserStorage(request)?.setItem(sessionKey,JSON.stringify({generation:c.generation,entries}));}catch{/* Storage denied/full: bounded memory cache still works. */}}
// Cache Storage can reuse large public image-bearing results across navigation.
// It is never a network proxy or offline fallback and never stores authenticated data.
const cacheBucket='apparition-public-catalogue-v1';
async function persistent(request,key){if(!browserStorage(request)||!globalThis.caches||!globalThis.crypto?.subtle)return null;try{const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(key));const hash=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');return {bucket:await caches.open(cacheBucket),key:new URL('/__public-catalogue-cache/'+hash,globalThis.location.href).href};}catch{return null;}}
async function persistentRead(request,key){const target=await persistent(request,key);if(!target)return null;try{const hit=await target.bucket.match(target.key);if(!hit)return null;const expires=Number(hit.headers.get('x-public-expires')),bytes=Number(hit.headers.get('x-public-bytes'));if(!Number.isFinite(expires)||!Number.isFinite(bytes)||expires<=Date.now()||expires>Date.now()+publicCachePolicy.maxAgeMs||bytes<0||bytes>publicCachePolicy.maxBytes||hit.headers.get('x-public-generation')!==String(generation(request))){await target.bucket.delete(target.key);return null;}const rows=await hit.json();return Array.isArray(rows)?{rows,expires}:null;}catch{return null;}}
async function persistentWrite(request,key,rows,expires,before){const target=await persistent(request,key);if(!target||before!==generation(request))return;try{const body=JSON.stringify(rows),bytes=new TextEncoder().encode(body).length;if(bytes>publicCachePolicy.maxBytes)return;await target.bucket.put(target.key,new Response(body,{headers:{'Content-Type':'application/json','x-public-expires':String(expires),'x-public-bytes':String(bytes),'x-public-generation':String(before)}}));const entries=[];for(const entry of await target.bucket.keys()){const value=await target.bucket.match(entry),size=Number(value.headers.get('x-public-bytes'));if(Number(value.headers.get('x-public-expires'))<=Date.now()||value.headers.get('x-public-generation')!==String(generation(request)))await target.bucket.delete(entry);else entries.push({entry,size});}let total=entries.reduce((n,e)=>n+e.size,0);while(entries.length>publicCachePolicy.maxEntries||total>publicCachePolicy.maxBytes){const oldest=entries.shift();total-=oldest.size;await target.bucket.delete(oldest.entry);}}catch{/* Browser storage is optional, never required for live reads. */}}
export async function readPublicRows({config,request=globalThis.fetch,maxAgeMs=publicCachePolicy.maxAgeMs},table,query,label='Public '+table){
 if(!['catalogue_components','catalogue_delivery_v2','catalogue_wiring_kits','catalogue_options','kit_permitted_components'].includes(table))throw Error('Unsupported public catalogue resource.');
 if(typeof request!=='function')throw Error('Public request transport required.');
 if(!Number.isFinite(maxAgeMs)||maxAgeMs<0||maxAgeMs>publicCachePolicy.maxAgeMs)throw Error('Invalid public cache expiry.');
 const url=config.url+'/rest/v1/'+table+query,key=config.publishableKey+' '+url,c=cache(request),hit=c.entries.get(key);
 if(maxAgeMs&&hit&&hit.expires>Date.now())return structuredClone(hit.rows);
 let reads=pending.get(request);if(!reads){reads=new Map();pending.set(request,reads);}
 let load=reads.get(key);if(!load){const before=generation(request);load=(async()=>{if(maxAgeMs){const saved=await persistentRead(request,key);if(saved&&before===generation(request)){store(request,c,key,saved.rows,saved.expires);return saved.rows;}}const response=await request(url,{cache:'no-store',headers:{apikey:config.publishableKey,Accept:'application/json'}});if(!response.ok)throw Error(label+' is unavailable ('+response.status+'). No browser-local data was used. No local configuration was substituted.');const rows=await response.json();if(!Array.isArray(rows))throw Error('Invalid '+label+' response.');if(maxAgeMs&&before===generation(request)){const expires=Date.now()+maxAgeMs;store(request,c,key,rows,expires);await persistentWrite(request,key,rows,expires,before);}return rows;})();reads.set(key,load);load.finally(()=>{if(reads.get(key)===load)reads.delete(key);}).catch(()=>{});}
 return structuredClone(await load);
}
